# hermes-terminal: plain `hermes` opens the conversation "Hermes's Terminal" (pinned in the Hermes app)
# with a recap of where you stopped. `hermes-new` = a separate new conversation. Generated by setup.py.
HERMES_TERMINAL_SCRIPT='__SCRIPT__'
HERMES_TERMINAL_PYTHON='__PYTHON__'
hermes_hook_open_50_terminal() {
  _started="$(date +%s)"
  _id="$("$HERMES_TERMINAL_PYTHON" "$HERMES_TERMINAL_SCRIPT" open 2>/dev/null | tail -n 1)"
  if [ -n "$_id" ]; then command hermes --resume "$_id"; else command hermes; fi
  echo "Saving the recap..."
  "$HERMES_TERMINAL_PYTHON" "$HERMES_TERMINAL_SCRIPT" close "$_started" 2>/dev/null
}
